import json,glob,os
CONF={"lhasa_apso":("Lhasa Apso","Shih Tzu, Maltese, Yorkshire Terrier, Havanese","a Lhasa Apso has a very long straight floor-length coat parted in the center, beard and moustache, medium-length muzzle, tail curled over the back, and NO topknot/ponytail/bow"),
"miniature_pinscher":("Miniature Pinscher","Doberman Pinscher, Chihuahua, Italian Greyhound, Whippet, Manchester Terrier","a Miniature Pinscher is a toy dog with a compact nearly square body, short neck, rounded skull, short blunt muzzle, medium-small erect ears; a Doberman has a long narrow head, long muzzle, tall neck; a Chihuahua has huge ears and a domed apple head"),
"vira_lata":("Vira-lata (Brazilian SRD caramel street dog)","Beagle, Labrador, Pit Bull, Whippet/Greyhound, Hound, Jack Russell","a Vira-lata is a generic lean medium mixed-breed street dog with a short coat, semi-erect triangular folded-tip ears, lean wedge muzzle, long thin tail; it must NOT have long drooping beagle/hound ears, tricolor beagle patches, or a heavy pit-bull jaw")}
if __name__=="__main__":
    R=[]
    for f in sorted(glob.glob("out/nb2/m1/*.png")):
        n=os.path.basename(f)[:-4]; slug=[s for s in CONF if s in n][0]; nm,conf,desc=CONF[slug]
        th="continuous single-line" if "_line_" in n else "geometric polygon"
        R.append({"id":n,"images":[f],"prompt":f"You are a strict dog-breed illustrator and print-on-demand art director. The image is a {th} line-art design: a small FRONT head emblem (left) and a full-body sitting dog (right) that are supposed to be a {nm}. Facts: {desc}. Commonly confused with: {conf}. Judge critically like a customer looking at a printed T-shirt. Return ONLY JSON: {{\"breed_identity\":0-10 (would a dog expert instantly say {nm}? 10=unmistakable; deduct hard if it looks like a confusable breed),\"looks_like\":\"which breed it most looks like\",\"head_back_match\":0-10 (front head and full body clearly same dog),\"completeness\":0-10 (all ears, tail, 4 legs and paws complete, nothing cut off, no stray marks),\"anatomy\":0-10 (no malformed anatomy, lines clean),\"appeal\":0-10,\"sitting\":true/false (is the full-body dog sitting),\"problems\":[short strings]}}"})
    json.dump(R,open("scripts/nb_req1.json","w"),indent=1); print(len(R))
